def chain_follow(WELL_FORMED, WELL_FORMED_CHAIN):
    chain = []
    current = WELL_FORMED_CHAIN[0]
    for pair in WELL_FORMED_CHAIN[1:]:
        next_item = pair[0]
        if next_item == current:
            current = next_item
        else:
            chain.append(current)
            current = next_item
    chain.append(current)
    return chain
